package dev.theredstonee.trsclient.core.map.session;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class WorldCatalogTest {
 @Test void tenRemoteOverworldsUseSeparatePersistentNamespaces(@TempDir Path dir)throws Exception{WorldCatalog c=new WorldCatalog(dir.resolve("worlds.json"));Map<String,String> keys=new HashMap<>();for(int i=0;i<10;i++){String id="survival-"+i;keys.put(id,c.begin(new Object(),"mp:same-server",id));}assertEquals(10,new HashSet<>(keys.values()).size());WorldCatalog restarted=new WorldCatalog(dir.resolve("worlds.json"));for(int i=9;i>=0;i--){String id="survival-"+i;assertEquals(keys.get(id),restarted.begin(new Object(),"mp:same-server",id));}}
 @Test void unidentifiedSessionsNeverMergeAndSavedWorldCanBeSelectedExplicitly(@TempDir Path dir)throws Exception{WorldCatalog c=new WorldCatalog(dir.resolve("worlds.json"));Object a=new Object();String first=c.begin(a,"hypixel",null),id=c.activeId();c.rename("Survival A");c.rotate(1);Object b=new Object();String second=c.begin(b,"hypixel",null);assertNotEquals(first,second);c.select(id);assertEquals(first,c.begin(b,"hypixel",null));assertEquals(1,c.turns());assertEquals("Survival A",c.name());assertEquals(2,c.entries().size());}
 @Test void lateAuthoritativeIdChangesNamespaceWithoutDeletingPendingWorld(@TempDir Path dir)throws Exception{WorldCatalog c=new WorldCatalog(dir.resolve("worlds.json"));Object level=new Object();String pending=c.begin(level,"server",null);String named=c.begin(level,"server","42");assertNotEquals(pending,named);assertEquals(named,c.begin(level,"server","42"));assertEquals(2,c.entries().size());}
 @Test void manualChoiceSurvivesAnUnrelatedOrLateServerIdInSameSession(@TempDir Path dir)throws Exception{WorldCatalog c=new WorldCatalog(dir.resolve("worlds.json"));c.begin(new Object(),"server","A");String id=c.activeId(),key=c.namespace();Object level=new Object();c.begin(level,"server","B");c.select(id);assertEquals(key,c.begin(level,"server","B"));}
 @Test void rotationPersistsAndDoesNotCreateAnotherWorld(@TempDir Path dir)throws Exception{Path file=dir.resolve("worlds.json");WorldCatalog c=new WorldCatalog(file);String key=c.begin(new Object(),"sp:A","local");for(int i=0;i<7;i++)c.rotate(1);WorldCatalog restarted=new WorldCatalog(file);assertEquals(key,restarted.begin(new Object(),"sp:A","local"));assertEquals(3,restarted.turns());assertEquals(1,restarted.entries().size());}
 @Test void serverAddressesAndIdentifiersBothSeparateWorlds(@TempDir Path dir)throws Exception{WorldCatalog c=new WorldCatalog(dir.resolve("worlds.json"));String a=c.begin(new Object(),"server-A","1"),b=c.begin(new Object(),"server-B","1");assertNotEquals(a,b);}
 @Test void invalidFileIsPreservedAndNotSilentlyOverwritten(@TempDir Path dir)throws Exception{Path file=dir.resolve("worlds.json");Files.write(file,"broken".getBytes("UTF-8"));assertThrows(java.io.IOException.class,()->new WorldCatalog(file));assertEquals("broken",new String(Files.readAllBytes(file),"UTF-8"));}
}
